def refs():
    return [{**s, "subject": "science", "observedPattern": "公立學校公開自然／理化試題常用碰撞、推牆、氣球、划船與受力圖情境考查第三運動定律、力的作用對象與系統邊界；本題只取能力方向並重新設計情境、數據與選項。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for s in SOURCES]


def make(n, prompt, options, answer, explanation, strategy, steps, difficulty):
    return {"id": f"question-science-content-eb-iv-13-{n}", "subject": "science", "type": "single-choice", "prompt": prompt, "options": [{"id": k, "text": v} for k, v in options.items()], "knowledgeIds": [KG], "difficulty": difficulty, "answer": {"value": answer, "explanation": explanation}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0]["url"], "sourceLocator": "三筆公立學校公開自然／理化資料僅作作用力與反作用力、碰撞、受力圖與系統判讀的能力方向研究；未複製原題、選項、圖表或答案。", "authoringNote": "依官方課綱、KG 與公立學校公開試題能力方向獨立改寫，待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-12", "lessonId": LESSON, "examPatternRefs": refs(), "solutionStrategy": strategy, "solutionSteps": steps}


Q = [
    make(1, "小明用手向右推牆。關於手與牆之間的作用力與反作用力，下列何者正確？", {"A": "手推牆向右，牆推手向左，兩力大小相等", "B": "只有手受到力，牆不會受到力", "C": "牆的反作用力比手的作用力大，所以手會受傷", "D": "反作用力要等手停止推牆後才出現"}, "A", "手對牆的推力與牆對手的推力同時存在、大小相等、方向相反，且分別作用在不同物體上。", "先寫出『誰對誰施力』，再檢查方向、大小與作用對象。", ["辨認互相作用的兩個物體是手與牆。", "寫出手對牆的推力方向向右。", "反作用力是牆對手的推力，方向向左。", "第三定律要求兩力大小相等且同時發生。", "因此選手推牆向右、牆推手向左且大小相等。"], "easy"),
    make(2, "兩台小車碰撞時，左車感測器顯示受到右向力 18 N。理想情況下，右車感測器應顯示何者？", {"A": "受到右向 18 N 的力", "B": "受到左向 18 N 的力", "C": "受到左向 9 N 的力", "D": "不會受到力，因為碰撞力會互相抵消"}, "B", "左車受到右車向右的力，右車同時受到左車向左的力；依第三定律，兩力大小相等、方向相反，因此為左向 18 N。", "將每個感測器的受力對象分開，不把兩台車的力直接畫在同一物體上。", ["確認左車受到右向 18 N。", "找出成對的另一個力：右車受到左車的力。", "第三定律使大小仍為 18 N。", "方向必與左車讀值相反，為向左。", "所以右車感測器應讀左向 18 N。"], "medium"),
    make(3, "下列哪一組力最符合牛頓第三運動定律的一對力？", {"A": "地球向下拉物體的重力與地面向上推物體的支持力", "B": "球受到球棒向右的力與球受到地面向左的摩擦力", "C": "腳向後推地面的力與地面向前推腳的力", "D": "物體的重力與物體受到的加速度"}, "C", "腳對地面與地面对腳是同一接觸事件中的兩個力，大小相等、方向相反，且分別作用在腳與地面。A 是同一物體可能受到的兩個外力，不一定成對。", "檢查兩力是否來自同一互動，且作用在兩個不同物體上。", ["逐項找出每個力的施力者與受力者。", "第三定律的一對力必須互為彼此作用。", "腳對地面與地面对腳符合相同接觸互動。", "兩力作用在不同物體，方向相反且同時發生。", "因此選腳推地面與地面推腳。"], "medium"),
    make(4, "畫『人』的受力圖時，腳對地面的力與地面对腳的力應如何處理？", {"A": "兩個力都畫在人的受力圖上並相消", "B": "只畫地面对腳的力；腳對地面的力作用在地面，不畫在人身上", "C": "兩個力都不能畫，因為是作用反作用", "D": "把腳對地面的力改畫成重力"}, "B", "腳對地面的力作用在地面，不是作用在人身上的力；人的受力圖只畫地面對腳等作用於人的外力。成對力不能因大小相等就畫在同一物體上相消。", "先選定研究物體，再只放入作用在該物體上的力。", ["指定研究對象為人。", "列出真正作用在人身上的力。", "地面对腳的力作用在人身上，應畫入。", "腳對地面的力作用在地面，不應畫入人的圖。", "因此不能把這一對力畫在同一人的受力圖中相消。"], "hard"),
    make(5, "氣球放開後向左移動，較合理的作用與反作用描述是？", {"A": "氣球把空氣向右推出，空氣對氣球向左推", "B": "氣球受到一個沒有來源的向左慣性力", "C": "空氣只被排出，沒有對氣球施力", "D": "氣球向左的力比空氣向右的力大，才符合第三定律"}, "A", "氣球對排出空氣施加向右的力，空氣同時對氣球施加向左的力；兩力大小相等、方向相反，作用在不同物體。", "追蹤被排出的物質與裝置本體，配對兩者的互相作用。", ["辨認互動的兩物體是氣球與排出的空氣。", "氣球把空氣向右推出。", "空氣對氣球的力方向相反，向左。", "兩力大小相等且同時發生。", "所以氣球因空氣反推而向左移動。"], "easy"),
    make(6, "碰撞後較輕的小車速度改變較大。下列推論何者不正確？", {"A": "兩車互相作用的碰撞力大小相等", "B": "較輕車可能因質量較小而有較大加速度", "C": "較輕車受到的反作用力一定比重車大", "D": "速度改變大小不能單獨用來判斷互動力大小"}, "C", "第三定律要求兩車彼此的碰撞力大小相等；較輕車速度改變較大可由質量差異造成，不能推論它受到較大的作用力。", "分開比較力與加速度，避免把運動結果直接當成互動力大小。", ["先確認兩車是互相碰撞的一對物體。", "第三定律給出彼此碰撞力大小相等。", "加速度還受到各車質量影響。", "較輕車可能有較大速度改變，但不代表受力較大。", "因此不正確的是『較輕車反作用力較大』。"], "medium"),
    make(7, "研究兩台小車作為一個整體時，車與車之間的碰撞力應如何處理？", {"A": "把碰撞力列為整體的兩個外力", "B": "車間力屬於系統內力，理想上成對抵消；仍要檢查軌道等外力", "C": "只保留較重車受到的碰撞力", "D": "因內力抵消，所以整體一定不受任何外力"}, "B", "以兩車為系統時，車間碰撞力是系統內力，成對相加為零；但軌道摩擦、外界推力等仍可能是整體外力，不能一概說完全不受力。", "先畫出系統邊界，再分類內力與外力。", ["把兩台車一起圈成研究系統。", "車對車的碰撞力雙方都在系統內。", "這對內力大小相等、方向相反，可在整體合力中抵消。", "軌道或外界對車的力仍在系統外，必須另列。", "所以正確描述是內力抵消但外力仍需檢查。"], "hard"),
    make(8, "划船時，船槳向後推水，船較可能向前移動。下列說法何者正確？", {"A": "水對船槳向前的力是船槳對水向後的力的反作用，兩者作用在不同物體", "B": "船槳對水的力比水對船槳的力大", "C": "只有船槳受力，水不受力", "D": "船前進代表反作用力消失"}, "A", "船槳對水向後施力，水同時對船槳向前施力；兩力大小相等、方向相反，分別作用在水與船槳。", "不要把船前進的結果誤當成兩力大小不相等，先配對施力者與受力者。", ["辨認互動雙方為船槳與水。", "船槳對水的力方向向後。", "水對船槳的力方向向前。", "第三定律使兩力大小相等且同時存在。", "船受到的其他外力與質量共同決定是否向前加速。"], "medium"),
    make(9, "一名學生跳起時向下壓地面，地面对學生的向上力使學生加速上升。哪一項最能避免誤解？", {"A": "地面對學生的力比學生對地面的力大", "B": "兩力大小相等，但學生的加速度由他所受的合力與質量決定", "C": "作用力與反作用力作用在同一學生身上", "D": "學生沒有對地面施力，只有地面推學生"}, "B", "學生對地面與地面对學生的力大小相等、方向相反，作用在不同物體；學生是否上升要看學生所受全部外力的合力與質量。", "把第三定律的力相等與第二定律的加速度結果分開判斷。", ["列出學生與地面這兩個互動物體。", "學生向下推地面，地面向上推學生。", "兩力大小相等，不因學生上升就變成不相等。", "學生的加速度取決於作用在學生上的合力與質量。", "因此選兩力相等但加速度另由合力與質量決定。"], "medium"),
    make(10, "兩個力感測器的碰撞曲線在接觸期間大小近似相同、方向相反，但峰值時間相差一小段。最合理的判讀是？", {"A": "第三定律失效，因為峰值沒有完全同時", "B": "只要方向相反，就可確定沒有測量誤差", "C": "資料在測量誤差範圍內支持理想的成對力，仍應檢查同步與校正", "D": "兩車受到的力一定不同，因為曲線不完全重合"}, "C", "理想定律要求同一互動中的兩力同時、等大、反向；真實感測器可能有取樣、同步、零點與碰撞偏差，因此應校正後判斷資料是否在誤差範圍內支持模型。", "把理想模型與實驗測量誤差分開，先檢查資料品質再下結論。", ["確認兩條曲線來自同一碰撞接觸事件。", "比較符號、大小與接觸時間，而不只看峰值位置。", "考慮取樣不同步、零點與車體碰撞造成的偏差。", "若差異落在誤差範圍內，資料仍可支持第三定律模型。", "因此最合理是先校正同步與誤差後再判讀。"], "hard"),
]

for q in Q:
    (OUT / f"{q['id']}.json").write_text(json.dumps(q, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
